import {z} from 'zod';
import {AtomValueSchema, AtomRefSchema, ComparisonSchema, EffectSchema, type Guard} from './symbolic-graph.js';
import type {SymbolicModel} from './playtest/symbolic-engine.js';
import {symbolicAtomKey} from './playtest/symbolic-engine.js';

// Generated by the compiler, never by an additional model request. The verified
// completed-action plan remains the witness; these are the game integration rules.
const Condition = z.object({all: z.array(ComparisonSchema).max(72)}).strict();
const Id = z.string().min(1).max(240);
export const AddedChapterSymbolSchema=z.object({
  ref:AtomRefSchema,name:z.string().trim().min(1).max(100),meaning:z.string().trim().max(500),
  type:z.enum(['boolean','number']),initial:AtomValueSchema.shape.value,
  changeMode:z.enum(['free','irreversible']),
}).strict().refine(s=>typeof s.initial===(s.type==='boolean'?'boolean':'number'),'심볼의 값 형식과 초기값이 다릅니다.');
export type AddedChapterSymbol=z.infer<typeof AddedChapterSymbolSchema>;
export const ChapterGameplaySchema = z.object({
  format: z.literal('chapter-gameplay-v1'),
  branchPolicy: z.literal('existing-symbol-results-v1').optional(),
  startEventId: Id,
  initialState: z.array(AtomValueSchema).max(256),
  addedSymbols:z.array(AddedChapterSymbolSchema).max(80).optional(),
  events: z.array(z.object({
    id: Id, startTrigger: Id, entryCondition: Condition, entryAlternatives:z.array(Condition).min(1).max(256).optional(), endingId: z.string().nullable(),
    signals: z.array(z.object({
      id: Id, label: z.string().min(1).max(240), condition: Condition,
      effects: z.array(EffectSchema).max(24), oncePerVisit: z.boolean(),
    }).strict()).max(256),
    exits: z.array(z.object({
      to: Id, requiredSignal: Id, condition: Condition,
    }).strict()).max(256),
  }).strict()).min(1).max(64),
  endings: z.array(z.object({endingId: z.string(), condition: Condition}).strict()).max(6),
}).strict();
export type ChapterGameplay = z.infer<typeof ChapterGameplaySchema>;
export type GameplayEvent = ChapterGameplay['events'][number];
export type GameplaySignal = GameplayEvent['signals'][number];

const eventId = (id: string) => id.replace(/^s_/, '');
export const gameplaySignalId = (from: string, to: string) => `play:${from}:${to}`;
const unique = (all: Guard['all']): Guard['all'] => [...new Map(all.map(c => [JSON.stringify(c), c])).values()];

/** A completed beat becomes a gameplay result inside its preceding event.
 * Its target scene is entered ONLY after the gameplay signal and start trigger.
 * Preconditions on changed atoms belong to the signal, never to the result scene.
 */
export function compileChapterGameplay(model: SymbolicModel): ChapterGameplay {
  const events = model.draft.situations.map(scene => {
    const id = eventId(scene.id);
    const outgoing = model.draft.transitions.filter(t => t.from === scene.id);
    return {
      id, startTrigger: `start:${id}`, entryCondition: scene.precondition, endingId: scene.endingId,
      signals: outgoing.map(t => ({
        id: gameplaySignalId(id, eventId(t.to)), label: t.label,
        condition: t.precondition, effects: t.effects, oncePerVisit: true as const,
      })),
      exits: outgoing.map(t => {
        const changed = new Set(t.effects.map(e => symbolicAtomKey(e.ref)));
        const target = model.draft.situations.find(s => s.id === t.to)!;
        return {
          to: eventId(t.to), requiredSignal: gameplaySignalId(id, eventId(t.to)),
          condition: {all: unique([
            ...t.precondition.all.filter(c => !changed.has(symbolicAtomKey(c.ref))),
            ...t.effects.filter(e => e.op === 'set').map(e => ({ref: e.ref, op: 'eq' as const, value: e.value})),
            ...target.precondition.all,
          ])},
        };
      }),
    };
  });
  return ChapterGameplaySchema.parse({format: 'chapter-gameplay-v1', startEventId: eventId(model.draft.startSituationId), initialState: model.draft.initialState, events, endings: model.draft.endingRules});
}
